using UnityEngine;

namespace Wickfall.UI
{
    /// <summary>The interface art (PDF §3 "Interface"), generated by Tools/art and wired by WICKFALL > Setup.</summary>
    [CreateAssetMenu(menuName = "WICKFALL/Visuals/HUD Sprites", fileName = "HudSprites")]
    public sealed class HudSprites : ScriptableObject
    {
        [Tooltip("Candle that melts down: 8 fill states, full first (PDF: \"8 fill states\").")]
        public Sprite[] candleStates = new Sprite[8];
        [Tooltip("Height of the candle top in each state, in pixels from the bottom of the sprite.")]
        public float[] candleTops = new float[8];
        [Tooltip("Flame animation frames, one row per FlameId (pre-tinted for the UI).")]
        public Sprite[] flameAmber, flameBlue, flameGreen, flameWhite, flameCrimson;
        [Tooltip("The five 16x16 flame icons with five silhouettes (PDF).")]
        public Sprite[] flameIcons = new Sprite[5];
        public Sprite flameIconLocked;
        public Sprite wheelRing;
        public Sprite wheelSocket;
        public Sprite wheelSocketSelected;
        public Sprite shardIcon;
        public Sprite dodgeFull;
        public Sprite dodgeEmpty;
        public Sprite sootIcon;
        public Sprite lightCutIcon;
        public Sprite panelFrame;
        public Sprite keyCap;
        public Sprite relicIconsSheet;
        public Sprite[] relicIcons = new Sprite[6];

        public Sprite[] Flame(FlameId id)
        {
            switch (id)
            {
                case FlameId.Blue: return flameBlue;
                case FlameId.Green: return flameGreen;
                case FlameId.White: return flameWhite;
                case FlameId.Crimson: return flameCrimson;
                default: return flameAmber;
            }
        }
    }
}
